  1→import express, { Request, Response } from "express";
  2→import { query, AgentDefinition, SettingSource, HookCallbackMatcher } from "@anthropic-ai/claude-agent-sdk";
  3→import { Langfuse } from "langfuse";
  4→import { mkdirSync, writeFileSync, existsSync, readdirSync, readFileSync } from "fs";
  5→import { homedir } from "os";
  6→import { join } from "path";
  7→import type { QueryRequest, HealthResponse } from "./types.js";
  8→
  9→// Claude CLI requires certain directories/files under ~/.claude to exist.
 10→// The container uses a tmpfs mount at ~/.claude which starts empty, so we
 11→// create the expected structure at startup.
 12→const claudeDir = join(homedir(), ".claude");
 13→for (const sub of ["debug", "projects"]) {
 14→  const dir = join(claudeDir, sub);
 15→  if (!existsSync(dir)) {
 16→    mkdirSync(dir, { recursive: true });
 17→  }
 18→}
 19→const settingsFile = join(claudeDir, "remote-settings.json");
 20→if (!existsSync(settingsFile)) {
 21→  writeFileSync(settingsFile, "{}");
 22→}
 23→
 24→// Skills are bind-mounted at the project-level path (/app/.claude/skills/)
 25→// so the CLI subprocess (spawned by the SDK with cwd=/app/) discovers them.
 26→const SKILLS_DIR = join(process.cwd(), ".claude", "skills");
 27→
 28→function isSkillDisabled(skillPath: string): boolean {
 29→  try {
 30→    const text = readFileSync(skillPath, "utf-8");
 31→    if (!text.startsWith("---")) return false;
 32→    const end = text.indexOf("---", 3);
 33→    if (end === -1) return false;
 34→    const frontmatter = text.slice(3, end);
 35→    for (const line of frontmatter.split("\n")) {
 36→      if (line.trim().startsWith("disabled:") && line.trim().endsWith("true")) {
 37→        return true;
 38→      }
 39→    }
 40→  } catch {
 41→    // ignore read errors
 42→  }
 43→  return false;
 44→}
 45→
 46→function discoverSkills(): Set<string> {
 47→  if (!existsSync(SKILLS_DIR)) return new Set();
 48→  return new Set(
 49→    readdirSync(SKILLS_DIR, { withFileTypes: true })
 50→      .filter((d) => {
 51→        if (!d.isDirectory()) return false;
 52→        const skillPath = join(SKILLS_DIR, d.name, "SKILL.md");
 53→        return existsSync(skillPath) && !isSkillDisabled(skillPath);
 54→      })
 55→      .map((d) => d.name)
 56→  );
 57→}
 58→
 59→// Log initial skills at startup
 60→console.log(`[sidecar] Initial skills: ${[...discoverSkills()].join(", ") || "(none)"}`);
 61→
 62→const skillAllowlistHook: HookCallbackMatcher = {
 63→  matcher: "Skill",
 64→  hooks: [
 65→    async (input) => {
 66→      const currentSkills = discoverSkills();
 67→      const toolInput = (input as Record<string, unknown>).tool_input as Record<string, unknown> | undefined;
 68→      const skillName = toolInput?.skill as string | undefined;
 69→      // Allow plugin-namespaced skills (e.g. "data:sql-queries") — the SDK's
 70→      // plugin system handles their discovery, so we only validate local skills.
 71→      if (skillName && skillName.includes(":")) {
 72→        return {};
 73→      }
 74→      if (skillName && !currentSkills.has(skillName)) {
 75→        return {
 76→          hookSpecificOutput: {
 77→            hookEventName: "PreToolUse" as const,
 78→            permissionDecision: "deny" as const,
 79→            permissionDecisionReason: `Skill "${skillName}" is not in the allowlist.`,
 80→          },
 81→        };
 82→      }
 83→      return {};
 84→    },
 85→  ],
 86→};
 87→
 88→// Initialize Langfuse if credentials are available (reads from env vars
 89→// LANGFUSE_PUBLIC_KEY, LANGFUSE_SECRET_KEY, LANGFUSE_BASE_URL automatically)
 90→let langfuse: Langfuse | null = null;
 91→if (process.env.LANGFUSE_PUBLIC_KEY && process.env.LANGFUSE_SECRET_KEY) {
 92→  langfuse = new Langfuse();
 93→  console.log("[sidecar] Langfuse tracing enabled");
 94→}
 95→
 96→const app = express();
 97→app.use(express.json({ limit: "10mb" }));
 98→
 99→const PORT = parseInt(process.env.PORT || "3000", 10);
100→
101→// Per-request abort tracking — avoids a global variable whose cleanup in one
102→// request's `finally` block can clobber a concurrently-started request.
103→let nextRequestId = 0;
104→const activeAborts = new Map<number, AbortController>();
105→
106→// How long (ms) to wait for the SDK iterator to yield a message before
107→// aborting.  Resets on every message so active multi-turn queries are not
108→// interrupted.  Covers cases where the CLI subprocess hangs on startup
109→// (e.g. broken session resume, unreachable MCP server).
110→const SDK_IDLE_TIMEOUT_MS = parseInt(process.env.SDK_IDLE_TIMEOUT_MS || "600000", 10);
111→
112→// Timeout (ms) for pre-flight reachability checks against MCP / API URLs.
113→const PREFLIGHT_TIMEOUT_MS = 10_000; // 10 seconds
114→
115→app.get("/health", (_req: Request, res: Response) => {
116→  const response: HealthResponse = { status: "ok" };
117→  res.json(response);
118→});
119→
120→app.post("/query", async (req: Request, res: Response) => {
121→  const body = req.body as QueryRequest;
122→
123→  if (!body.message || !body.system_prompt) {
124→    res.status(400).json({ error: "message and system_prompt are required" });
125→    return;
126→  }
127→
128→  // Set up SSE headers
129→  res.setHeader("Content-Type", "text/event-stream");
130→  res.setHeader("Cache-Control", "no-cache");
131→  res.setHeader("Connection", "keep-alive");
132→  res.setHeader("X-Accel-Buffering", "no");
133→  res.flushHeaders();
134→
135→  const abortController = new AbortController();
136→  const requestId = nextRequestId++;
137→  activeAborts.set(requestId, abortController);
138→
139→  // Merge per-request env overrides (e.g. Bifrost gateway URLs) with process env
140→  const sdkEnv: Record<string, string> = {};
141→  for (const [k, v] of Object.entries(process.env)) {
142→    if (v !== undefined) sdkEnv[k] = v;
143→  }
144→  if (body.env) {
145→    Object.assign(sdkEnv, body.env);
146→  }
147→  // Scrub Langfuse credentials so the agent subprocess cannot read them from
148→  // the inherited environment — matches backend subprocess behaviour.
149→  // The sidecar's own Langfuse client already holds the credentials internally.
150→  sdkEnv["LANGFUSE_PUBLIC_KEY"] = "";
151→  sdkEnv["LANGFUSE_SECRET_KEY"] = "";
152→
153→  let responseEnded = false;
154→
155→  // Detect client disconnect
156→  res.on("close", () => {
157→    if (!responseEnded) {
158→      abortController.abort();
159→    }
160→  });
161→
162→  // --- Langfuse tracing setup ---
163→  // Mirror the backend's session ID handling:
164→  //   - langfuse_session_id (from frontend for edit/delete) takes priority
165→  //   - session_id (CLI session from previous turn) as fallback
166→  const modelName = body.model || process.env.ORCHESTRATOR_MODEL || "claude-sonnet-4-6";
167→  const traceMessage = body.original_message || body.message;
168→  const traceInput: Record<string, unknown> = {
169→    message: traceMessage.substring(0, 500),
170→  };
171→  if (body.conversation_history && body.conversation_history.length > 0) {
172→    traceInput.conversation_history = body.conversation_history;
173→  }
174→  const trace = langfuse?.trace({
175→    name: "agent-chat",
176→    sessionId: body.langfuse_session_id || body.session_id || undefined,
177→    input: traceInput,
178→    metadata: { model: modelName, mode: "container" },
179→  });
180→
181→  // Per-turn usage tracking from stream events
182→  let currentGenUsage: { input?: number; output?: number } = {};
183→  // Accumulated messages for generation input context
184→  const accumulatedMessages: Array<{ role: string; content: unknown }> = [
185→    { role: "user", content: body.message },
186→  ];
187→
188→  // Collect stderr from the CLI subprocess for debugging
189→  const stderrLines: string[] = [];
190→
191→  // Declared here so `finally` can clear it even if `try` throws early
192→  let idleTimer: ReturnType<typeof setTimeout> | null = null;
193→
194→  try {
195→    // --- Pre-flight reachability checks ---
196→    // The CLI subprocess will hang silently if it can't reach the MCP SSE
197→    // server or the Bifrost LLM gateway.  Test connectivity first so we can
198→    // fail fast with a useful error message.
199→    const apiBase = sdkEnv["ANTHROPIC_BASE_URL"] || "";
200→    console.log(
201→      `[sidecar] reqId=${requestId} mcp_url=${body.mcp_server_url || "(none)"} api_base=${apiBase} session_id=${body.session_id || "(none)"}`
202→    );
203→
204→    if (body.mcp_server_url) {
205→      try {
206→        const mcpResp = await fetch(body.mcp_server_url, {
207→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
208→        });
209→        // SSE endpoints normally return 200 with text/event-stream; any
210→        // non-error status is fine — we just need to know the host is up.
211→        mcpResp.body?.cancel(); // don't consume the stream
212→        console.log(`[sidecar] MCP reachability OK (status=${mcpResp.status})`);
213→      } catch (e: unknown) {
214→        const reason = e instanceof Error ? e.message : String(e);
215→        throw new Error(
216→          `MCP server unreachable at ${body.mcp_server_url}: ${reason}. ` +
217→          `Check that BACKEND_BASE_URL is reachable from inside the container.`
218→        );
219→      }
220→    }
221→
222→    if (apiBase) {
223→      try {
224→        // Just a quick TCP-level check — Bifrost will return 4xx without
225→        // a real API key but that still proves reachability.
226→        const apiResp = await fetch(`${apiBase}/v1/models`, {
227→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
228→        });
229→        apiResp.body?.cancel();
230→        console.log(`[sidecar] Bifrost LLM gateway reachability OK (status=${apiResp.status})`);
231→      } catch (e: unknown) {
232→        const reason = e instanceof Error ? e.message : String(e);
233→        throw new Error(
234→          `Bifrost LLM gateway unreachable at ${apiBase}: ${reason}. ` +
235→          `Check that BIFROST_BASE_URL is reachable from inside the container.`
236→        );
237→      }
238→    }
239→
240→    // Convert agents payload from the backend into SDK AgentDefinition objects.
241→    // The SDK only accepts 'sonnet' | 'opus' | 'haiku' | 'inherit' for model.
242→    // Arbitrary strings (e.g. "openai/gpt-5.2") are silently rejected, causing
243→    // the agent to not be registered.  Validate and fall back to "inherit".
244→    const VALID_AGENT_MODELS = new Set(["sonnet", "opus", "haiku", "inherit"]);
245→    let sdkAgents: Record<string, AgentDefinition> | undefined;
246→    if (body.agents) {
247→      sdkAgents = {};
248→      for (const [name, def] of Object.entries(body.agents)) {
249→        const model = def.model && VALID_AGENT_MODELS.has(def.model)
250→          ? (def.model as AgentDefinition["model"])
251→          : "inherit";
252→        sdkAgents[name] = {
253→          description: def.description,
254→          prompt: def.prompt,
255→          ...(def.tools ? { tools: def.tools } : {}),
256→          model,
257→        };
258→      }
259→    }
260→
261→    // Append skill restriction so the model doesn't list or suggest
262→    // built-in skills that the PreToolUse hook would block anyway.
263→    // The CLI binary injects its own system reminder listing ALL skills
264→    // (including built-ins like "simplify"), so we must explicitly tell
265→    // the model to ignore any skills not in our allowlist.
266→    const currentSkills = discoverSkills();
267→    const allowedList = [...currentSkills].join(", ");
268→    const pluginSkillNote = " You may also invoke any plugin-namespaced skills (skills whose name contains ':', such as 'data:sql-queries', 'data:analyze', 'data:write-query', 'data:create-viz', 'data:explore-data', 'data:build-dashboard', 'data:validate', etc.) — these are provided by installed plugins and are always allowed.";
269→    const skillRestriction = currentSkills.size > 0
270→      ? `\n\nCRITICAL SKILL RESTRICTION: The ONLY local skills you may invoke with the Skill tool are: ${allowedList}. You may see other skills (like "simplify") listed in system reminders — those are NOT available to you and MUST be ignored. When asked about available skills, list ONLY: ${allowedList} (plus any plugin-namespaced skills). Never mention, suggest, or attempt to invoke any non-plugin skill not in this list.${pluginSkillNote} NOTE: The mcp__duckdb-data-agent__create_skill tool is always available for creating NEW skills — this restriction only applies to invoking existing skills via the Skill tool.`
271→      : `\n\nCRITICAL SKILL RESTRICTION: You have no local skills available to invoke with the Skill tool. You may see skills listed in system reminders — those are NOT available to you and MUST be ignored. Never mention, suggest, or attempt to invoke any non-plugin skills.${pluginSkillNote} NOTE: The mcp__duckdb-data-agent__create_skill tool is always available for creating NEW skills — this restriction only applies to invoking existing skills via the Skill tool.`;
272→
273→    const skillInstruction = body.skills?.length
274→      ? `\n\nIMPORTANT: The user has invoked the following skill(s): ${body.skills.map(s => `"/${s}"`).join(", ")}. You MUST use the Skill tool to invoke each skill (${body.skills.map(s => `"${s}"`).join(", ")}) before doing anything else.`
275→      : "";
276→
277→    // Common SDK options (without resume/prompt — those vary on retry)
278→    const baseOptions = {
279→      model: modelName,
280→      systemPrompt: body.system_prompt + skillInstruction + skillRestriction,
281→      allowedTools: [
282→        "Bash",
283→        "Read",
284→        "Write",
285→        "Edit",
286→        "Glob",
287→        "Grep",
288→        "Skill",
289→        "Task",
290→        "mcp__duckdb-data-agent__execute_sql",
291→        "mcp__duckdb-data-agent__ask_user_question",
292→        "mcp__duckdb-data-agent__render_chart",
293→        "mcp__duckdb-data-agent__create_skill",
294→        "mcp__duckdb-data-agent__save_memory",
295→        "mcp__duckdb-data-agent__recall_memories",
296→        "mcp__duckdb-data-agent__forget_memory",
297→      ] as string[],
298→      settingSources: ["project"] as SettingSource[],
299→      plugins: [{ type: "local" as const, path: "./plugins/data" }],
300→      hooks: { PreToolUse: [skillAllowlistHook] },
301→      permissionMode: "bypassPermissions" as const,
302→      allowDangerouslySkipPermissions: true,
303→      maxTurns: 20,
304→      includePartialMessages: true,
305→      abortController,
306→      env: sdkEnv,
307→      stderr: (line: string) => {
308→        stderrLines.push(line);
309→        console.error(`[sidecar:cli] ${line}`);
310→      },
311→      ...(sdkAgents ? { agents: sdkAgents } : {}),
312→      ...(body.mcp_server_url
313→        ? {
314→            mcpServers: {
315→              "duckdb-data-agent": {
316→                type: "sse" as const,
317→                url: body.mcp_server_url,
318→              },
319→            },
320→          }
321→        : {}),
322→    };
323→
324→    // Resume fallback: try with resume first. If the SDK yields a "result"
325→    // message with "No conversation found" (container was recreated and lost
326→    // the session), suppress that error and retry without resume, prepending
327→    // conversation history so the model has context.
328→    //
329→    // When resuming, the SDK reuses the original session's system prompt, so
330→    // skill changes (additions/deletions) since conversation start won't be
331→    // reflected.  Prepend an updated skill restriction to the user message so
332→    // the model always sees the current set of available skills.
333→    let useResume = !!body.session_id;
334→    let currentPrompt = useResume
335→      ? `${skillRestriction}\n\n${body.message}`
336→      : body.message;
337→    let retried = false;
338→
339→    queryLoop: for (let attempt = 0; attempt < 2; attempt++) {
340→      const sdkQuery = query({
341→        prompt: currentPrompt,
342→        options: {
343→          ...baseOptions,
344→          ...(useResume ? { resume: body.session_id } : {}),
345→        },
346→      });
347→
348→      console.log(
349→        `[sidecar] SDK query started model=${modelName} reqId=${requestId} attempt=${attempt} resume=${useResume}`
350→      );
351→
352→      idleTimer = setTimeout(() => {
353→        console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
354→        abortController.abort();
355→      }, SDK_IDLE_TIMEOUT_MS);
356→
357→      let resumeFailedNeedsRetry = false;
358→
359→      try {
360→        for await (const message of sdkQuery) {
361→          // Reset idle timer on every message
362→          if (idleTimer) { clearTimeout(idleTimer); }
363→          idleTimer = setTimeout(() => {
364→            console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
365→            abortController.abort();
366→          }, SDK_IDLE_TIMEOUT_MS);
367→
368→          if (responseEnded) break queryLoop;
369→
370→          // Intercept "No conversation found" result before forwarding
371→          if (useResume && !retried) {
372→            const msg = message as Record<string, unknown>;
373→            if (msg.type === "result" && msg.is_error) {
374→              const resultText = String(msg.result || "");
375→              const errors = ((msg.errors as string[]) || []).join(" ");
376→              if ((resultText + " " + errors).includes("No conversation found")
377→                  && body.conversation_history && body.conversation_history.length > 0) {
378→                console.log(`[sidecar] Resume failed ("No conversation found"), will retry with history reqId=${requestId}`);
379→                resumeFailedNeedsRetry = true;
380→                break; // Don't forward this error to the client
381→              }
382→            }
383→          }
384→
385→          // Forward each SDK message as an SSE data line
386→          res.write(`data: ${JSON.stringify(message)}\n\n`);
387→
388→          // --- Create Langfuse observations from SDK messages ---
389→          if (!trace) continue;
390→          const msg = message as Record<string, unknown>;
391→
392→          if (msg.type === "stream_event") {
393→            const event = (msg.event as Record<string, unknown>) || {};
394→            const eventType = event.type as string;
395→            if (eventType === "message_start") {
396→              const msgData = (event.message as Record<string, unknown>) || {};
397→              const usage = (msgData.usage as Record<string, number>) || {};
398→              currentGenUsage = { input: usage.input_tokens || 0 };
399→            } else if (eventType === "message_delta") {
